// End to end: the refresh run on fixtures must leave behind the same bytes the R refresh left behind (test/golden/<scenario>/expected,
// generated by test/oracle/gen_goldens.R with the clock pinned to 2026-11-26 15:00:00 UTC).

import { readFileSync } from "node:fs";
import { join } from "node:path";
import { describe, expect, it } from "vitest";
import { dataPaths } from "../config.ts";
import { buildSeasonStats, writeBaselineSeason, ANY_SEASON_MIN_ROWS } from "../dataSources.ts";
import { refreshData } from "../refreshData.ts";
import { fixtureHttp, listFiles, makeTempDir, stageInputs, TEST_DIR } from "./support.ts";

const NOW = new Date("2026-11-26T15:00:00Z");
// The golden files were made for the 2026 season; pinned here so bumping CURRENT_YEAR in config.ts does not change them.
const GOLDEN_YEAR = 2026;

const scenarios = [
  { name: "basic", fixtures: "fixtures", blankWhiff: false },
  { name: "edge", fixtures: "fixtures-edge", blankWhiff: false },
  { name: "refused", fixtures: "fixtures", blankWhiff: false },
  { name: "blank_whiff", fixtures: "fixtures", blankWhiff: true },
];

describe.each(scenarios)("scenario $name leaves exactly the files R left", ({ name, fixtures, blankWhiff }) => {
  it("matches every output file byte for byte", async () => {
    const dir = stageInputs(name);
    const logs: string[] = [];
    const { promoted } = await refreshData({
      paths: dataPaths(join(dir, "data")),
      now: NOW,
      currentYear: GOLDEN_YEAR,
      httpGet: fixtureHttp(fixtures, [], blankWhiff),
      log: (line) => logs.push(line),
    });

    const expectedRoot = join(TEST_DIR, "golden", name, "expected", "data");
    const expectedFiles = listFiles(expectedRoot);
    expect(listFiles(join(dir, "data"))).toEqual(expectedFiles);
    for (const file of expectedFiles) {
      expect(readFileSync(join(dir, "data", file), "utf8"), file).toBe(readFileSync(join(expectedRoot, file), "utf8"));
    }
    const status = Number(readFileSync(join(TEST_DIR, "golden", name, "exit_status"), "utf8").trim());
    expect(promoted ? 0 : 1).toBe(status);
    expect(logs.join("\n")).toContain(`Production files promoted: ${promoted ? "TRUE" : "FALSE"}`);
  });
});

describe("baseline files", () => {
  it.each([
    { scenario: "basic", year: 2025, fixtures: "fixtures" },
    { scenario: "edge", year: 2024, fixtures: "fixtures-edge" },
  ])("buildSeasonStats + writeBaselineSeason reproduce R's $scenario $year files", async ({ scenario, year, fixtures }) => {
    const stats = await buildSeasonStats(2025, { minRows: ANY_SEASON_MIN_ROWS, httpGet: fixtureHttp(fixtures), log: () => {} });
    const dir = makeTempDir();
    writeBaselineSeason(year, stats, dir, false, () => {});
    for (const kind of ["hitters", "pitchers"]) {
      const file = `baseline-${kind}-${year}.csv`;
      const expected = readFileSync(join(TEST_DIR, "golden", scenario, "inputs", "data", "baselines", file), "utf8");
      expect(readFileSync(join(dir, file), "utf8"), file).toBe(expected);
    }
  });
});
